const files = items.map(i => i.json);
const pick = files[Math.floor(Math.random() * files.length)];
return [{
  json: {
    fileId: pick.id,
    fileName: pick.name,
    webContentLink: pick.webContentLink, // usable direct link
    webViewLink: pick.webViewLink
  }
}];

// === Utilidades ===
const resp = $json.responses?.[0] || {};
const labelsAll = (resp.labelAnnotations || [])
  .map(l => ({ d: (l.description || '').toLowerCase().trim(), s: l.score || 0 }))
  .sort((a,b)=> b.s - a.s)
  .map(x => x.d);

const uniq = arr => [...new Set(arr.filter(Boolean))];
const stripAccents = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const toHash = s => '#'+ stripAccents(s).toLowerCase().replace(/\s+/g,'');

// === Palavras-chave de café (inglês + pt) ===
const coffeeKW = [
  'coffee','café','cafe','bean','beans','grão','grãos','espresso',
  'latte','cappuccino','mocha','barista','crema','grinder','moedor',
  'roast','torra','roasted coffee','filter coffee','café filtrado',
  'pour over','pour-over','coador manual','coador','chemex','v60',
  'aeropress','french press','prensa francesa','moka','moka pot',
  'portafilter','portafiltro','milk foam','espuma de leite','xícara','mug','cup','cafeteira'
];

// Seleciona rótulos relevantes a café
const uniqueLabels = uniq(labelsAll);
const coffeeHits = uniqueLabels.filter(l => coffeeKW.some(k => l.includes(k)));

// Foco nos termos
const focus = coffeeHits.length ? coffeeHits.slice(0, 8) : uniqueLabels.slice(0, 8);

// Resumo em pt-BR
const summaryPT = coffeeHits.length
  ? `Elementos de café detectados: ${focus.join(', ')}.`
  : `Elementos visuais relevantes: ${focus.join(', ')} (sem itens de café claros; conecte ao ritual do café).`;

// Hashtags candidatas em pt-BR (curadas + derivadas)
const curated = [
  '#jabocafe','#cafebrasileiro','#cafesespeciais','#graoscafe',
  '#moagem','#espressoperfeito','#coadormanual','#torra','#barista'
];
const derived = focus.map(toHash);
const candTags = uniq([...curated, ...derived]).slice(0, 10);

return [{
  json: {
    image_summary_pt: `${summaryPT} Tom: acolhedor, artesanal, brasileiro.`,
    image_labels_raw: uniqueLabels,
    coffee_terms: coffeeHits,
    image_candidate_hashtags: candTags
  }
}];

