const raw = $json.choices?.[0]?.message?.content;
if (!raw) throw new Error('Groq vazio');
let c;
try { c = JSON.parse(raw); } catch { throw new Error('JSON inválido do Groq'); }

// Limites
const words = s => (s||'').trim().split(/\s+/).filter(Boolean);
if (words(c.title).length > 5) c.title = words(c.title).slice(0,5).join(' ');
if (words(c.subtitle).length > 10) c.subtitle = words(c.subtitle).slice(0,10).join(' ');

// Caption ~150 palavras (tolerância)
const capWords = words(c.caption);
if (capWords.length > 160) c.caption = capWords.slice(0,150).join(' ');

// Hashtags no final (3–5, minúsculas)
const tags = (c.caption.match(/#[\p{L}\p{N}_]+/gu) || []);
if (tags.length < 3) throw new Error('Menos de 3 hashtags');
if (tags.length > 6) {
  // corta para 5
  const textoSemTags = c.caption.replace(/#[\p{L}\p{N}_]+/gu, '').trim();
  c.caption = `${textoSemTags}\n\n${tags.slice(0,5).join(' ')}`;
}
// Força minúsculas nas hashtags
c.caption = c.caption.replace(/#[\p{L}\p{N}_]+/gu, m => m.toLowerCase());

return [{ json: c }];

const slides =  $input.first().json.slides|| [];
if (!slides.length) throw new Error('No slides found');

const presentationId = $node['Drive: Copy Template'].json.id;   // ou $('Drive: Copy Template').json.id

return [{
  json: {
    presentationId,
    pageId: slides[0].objectId
  }
}];

const title = $('Generate JSON').first().json.title || '';
const subtitle = $('Generate JSON').first().json.subtitle|| '';
const body = $('Generate JSON').first().json.body_text || '';
const fileId = $('Code').first().json.fileId;
const imageUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;

return [{
  json: {
    requests: [
      { replaceAllText: {
          containsText: { text: '[[TITLE]]', matchCase: false },
          replaceText: title
      }},
      { replaceAllText: {
          containsText: { text: '[[SUBTITLE]]', matchCase: false },
          replaceText: subtitle
      }},
      { replaceAllText: {
          containsText: { text: '[[BODY]]', matchCase: false },
          replaceText: body
      }},
      { replaceAllShapesWithImage: {
          imageUrl,
          imageReplaceMethod: 'CENTER_INSIDE',
          containsText: { text: '[[IMAGE]]', matchCase: false }
      }}
    ]
  }
}];
